126	/**
127	 * Invoke the `onValidate` hook on every registered plugin and collect all
128	 * returned ValidationResult objects into a single flat array.
129	 *
130	 * Plugins that do not implement `onValidate` contribute nothing to the result.
131	 * The return value is always an array (never null/undefined).
132	 *
133	 * @param plugins Ordered list of registered plugins
134	 * @param persona Typed metadata for the persona being built
135	 * @param suite   The suite configuration object
136	 * @param target  The current build target (optional — forwarded to each plugin)
137	 * @returns       Flat array of all ValidationResult objects from all plugins
138	 */
139	export function runValidate(
140	  plugins: PersonaBuildPlugin[],
141	  persona: PersonaMetadata,
142	  suite: SuiteConfig,
143	  target?: TargetType,
144	): ValidationResult[] {
145	  const results: ValidationResult[] = [];
146	  for (const plugin of plugins) {
147	    if (typeof plugin.onValidate === 'function') {
148	      const pluginResults = plugin.onValidate(persona, suite, target);
149	      results.push(...pluginResults);
150	    }
151	  }
152	  return results;
153	}

  1	/**
  2	 * src/builders/persona-builder.ts
  3	 *
  4	 * Core build orchestrator for @mistralys/persona-builder.
  5	 *
  6	 * Exports three public functions:
  7	 *
  8	 *  1. buildPersona(personaYamlPath, suiteName, suiteConfig, sharedMeta,
  9	 *                  partialsMap, config, plugins, target, agentMap?)
 10	 *     — Builds a single persona for a single target. Returns a BuildResult.
 11	 *
 12	 *  2. buildSuite(suiteName, suiteConfig, config, plugins, target, agentMap?)
 13	 *     — Discovers all persona YAMLs for a suite, fires onSuiteInit, maps
 14	 *       buildPersona() over each, and returns BuildResult[].
 15	 *
 16	 *  3. build(config)
 17	 *     — Top-level entry point. Pre-scans all suites to build a cross-suite
 18	 *       agent name map, then iterates all suites × targets, calls
 19	 *       buildSuite() for each combination, and returns a BuildSummary.
 20	 *       Respects --check (no writes) and --strict (fail on warnings/errors).
 21	 */
