162	/**
163	 * Pre-scan all suites and build a cross-suite agent name map.
164	 *
165	 * For each persona across all configured suites, creates a context variable:
166	 *   key:   `agent_` + slug (hyphens → underscores)
167	 *   value: `"<name> v<version>"`
168	 *
169	 * Slug is taken from the persona YAML's `slug` field, falling back to the
170	 * filename stem. Version falls back to the suite's `default_version`, then
171	 * to `'0.0.0'`.
172	 *
173	 * @param config  Top-level BuildConfig with all suite definitions
174	 * @returns       Map of agent variable keys to display strings
175	 */
176	async function buildAgentNameMap(
177	  config: BuildConfig,
178	): Promise<Record<string, string>> {
179	  const agentMap: Record<string, string> = {};
180	
181	  for (const [, suiteConfig] of Object.entries(config.suites)) {
182	    const metaSubdir = suiteConfig.metaSubdir ?? 'meta';
183	    const sharedYamlPath = path.join(suiteConfig.srcDir, metaSubdir, '_shared.yaml');
184	    const sharedMeta = await loadRawYaml(sharedYamlPath);
185	    const defaultVersion =
186	      typeof sharedMeta['default_version'] === 'string'
187	        ? sharedMeta['default_version']
188	        : '0.0.0';
189	
190	    const personaYamls = await discoverSuitePersonaYamls(suiteConfig);
191	
192	    for (const yamlPath of personaYamls) {
193	      const persona = await loadPersonaYaml(yamlPath);
194	
195	      const slug =
196	        typeof persona['slug'] === 'string'
197	          ? persona['slug']
198	          : path.basename(yamlPath, '.yaml');
199	
200	      const name =
201	        typeof persona['name'] === 'string'
202	          ? persona['name']
203	          : slug;
204	
205	      const version =
206	        typeof persona['version'] === 'string'
207	          ? persona['version']
208	          : defaultVersion;
209	
210	      const underscoredSlug = slug.replace(/-/g, '_');
211	      const key = `agent_${underscoredSlug}`;
212	      agentMap[key] = `${name} v${version}`;
213	
214	      const slugKey = `agent_slug_${underscoredSlug}`;
215	      agentMap[slugKey] = slug;
216	    }
217	  }
218	
219	  return agentMap;
220	}
221	
222	/**
223	 * Build the merged template context for a single persona.
224	 *
225	 * Merge order (later values win):
226	 *   1. sharedMeta (suite-level defaults)
227	 *   2. per-persona YAML fields
228	 *   3. derived/computed fields (version fallback, etc.)
229	 *   4. agentMap entries (only for keys not already present)
230	 *
231	 * @param personaMeta  Per-persona YAML as a plain record
232	 * @param sharedMeta   Parsed `_shared.yaml` fields
233	 * @param agentMap     Cross-suite agent name map (injected by build())
234	 * @returns            Merged rendering context
235	 */
236	function buildContext(
237	  personaMeta: Record<string, unknown>,
238	  sharedMeta: Record<string, unknown>,
239	  agentMap: Record<string, string> = {},
240	  target?: TargetType,
241	  registry?: TargetRegistry,
242	): Record<string, unknown> {
243	  const version =
244	    typeof personaMeta['version'] === 'string'
245	      ? personaMeta['version']
246	      : typeof sharedMeta['default_version'] === 'string'
247	        ? sharedMeta['default_version']
248	        : '0.0.0';
249	
250	  // Merge base: shared first, persona overrides

251	  const merged: Record<string, unknown> = {
252	    ...sharedMeta,
253	    ...personaMeta,
254	    version,
255	  };
256	
257	  // ── Derived convenience fields (only set when not already provided) ───────
258	  // tools_list / tools_json — serialized from the `tools` array if present
259	  const tools = Array.isArray(merged['tools']) ? (merged['tools'] as string[]) : [];
260	  if (!('tools_list' in merged)) {
261	    merged['tools_list'] = serializeToolsList(tools);
262	  }
263	  if (!('tools_json' in merged)) {
264	    merged['tools_json'] = serializeTools(tools);
265	  }
266	
267	  // cc_tools_list / cc_tools_json — from `cc_tools` or fall back to `tools`
268	  const ccTools = Array.isArray(merged['cc_tools']) ? (merged['cc_tools'] as string[]) : tools;
269	  if (!('cc_tools_list' in merged)) {
270	    merged['cc_tools_list'] = serializeToolsList(ccTools);
271	  }
272	  if (!('cc_tools_json' in merged)) {
273	    merged['cc_tools_json'] = serializeTools(ccTools);
274	  }
275	
276	  // cc_file_name_stem — stem of cc_file_name (for default CC frontmatter template)
277	  if (!('cc_file_name_stem' in merged) && typeof merged['cc_file_name'] === 'string') {
278	    const ccFileName = merged['cc_file_name'] as string;
279	    merged['cc_file_name_stem'] = ccFileName.replace(/\.md$/, '');
280	  }
281	
282	  // da_file_name_stem — stem of da_file_name (for deep-agents output)
283	  if (!('da_file_name_stem' in merged) && typeof merged['da_file_name'] === 'string') {
284	    const daFileName = merged['da_file_name'] as string;
285	    merged['da_file_name_stem'] = daFileName.replace(/\.md$/, '');
286	  }
287	
288	  // da_tools_list / da_tools_json — from `da_tools` or fall back to `tools`
289	  // Intentionally gated on da_file_name: unlike cc_tools_list/cc_tools_json (always emitted for
290	  // every persona), da_* fields are absent when the persona has no deep-agents output file (AC-4).
291	  if (typeof merged['da_file_name'] === 'string') {
292	    const daTools = Array.isArray(merged['da_tools']) ? (merged['da_tools'] as string[]) : tools;
293	    if (!('da_tools_list' in merged)) {
294	      merged['da_tools_list'] = serializeToolsList(daTools);
295	    }
296	    if (!('da_tools_json' in merged)) {
297	      merged['da_tools_json'] = serializeTools(daTools);
298	    }
299	  }
300	
301	  // ── Cross-suite agent name variables ──────────────────────────────────────
302	  for (const [key, value] of Object.entries(agentMap)) {
303	    if (!(key in merged)) {
304	      merged[key] = value;
305	    }
306	  }
307	
308	  // ── Target flag injection ─────────────────────────────────────────────────
309	  if (target !== undefined) {
310	    if (registry && registry.has(target)) {
311	      // Inject all contextFlags declared in the target's registry definition.
312	      const flags = registry.get(target).contextFlags ?? {};
313	      for (const [key, value] of Object.entries(flags)) {
314	        merged[key] = value;
315	      }
316	    } else {
317	      // Fallback for targets not present in the registry.
318	      merged[`target_${target.replace(/-/g, '_')}`] = true;
319	    }
320	  }
321	
322	  return merged;
323	}
324	
325	// ---------------------------------------------------------------------------
326	// buildPersona — single persona × single target
327	// ---------------------------------------------------------------------------
328	
329	/**
330	 * Build a single persona for a single output target.
331	 *
332	 * Pipeline:
333	 *   1. Load sharedMeta + personaMeta (callers supply pre-loaded values)
334	 *   2. Build merged context
335	 *   3. Run onBuildContext plugin hooks (context accumulation)
336	 *   4. Resolve frontmatter template → render frontmatter
337	 *   5. Load content template
338	 *   6. Render body: partials → conditionals → variables → post-process
339	 *   7. Assemble final output (frontmatter + body)
340	 *   8. Run onPostRender plugin hooks (output chain)
341	 *   9. Run onValidate plugin hooks (validation collection)
342	 *  10. Determine output file path
343	 *  11. Write output file (unless check mode)
344	 *  12. Return BuildResult
345	 *
346	 * @param personaYamlPath  Absolute path to the persona YAML source file
347	 * @param suiteName        Identifier for the suite this persona belongs to
348	 * @param suiteConfig      Suite configuration object
349	 * @param sharedMeta       Pre-loaded `_shared.yaml` contents
350	 * @param partialsMap      Pre-loaded partials map (shared + suite-local merged)
351	 * @param config           Top-level BuildConfig
352	 * @param plugins          Registered plugins
353	 * @param target           Target output format
354	 * @param agentMap         Pre-built cross-suite agent name map
355	 * @param registry         Target registry to use. Defaults to `defaultRegistry`.
356	 *   **Two-registry limitation:** If you pass a custom `TargetRegistry` only
357	 *   to `build()` (via `config.targetRegistry`) and call `buildPersona()`
358	 *   directly without also passing that registry here, your custom targets
359	 *   will not be visible — `defaultRegistry` will be used instead. Either
360	 *   pass the same registry instance explicitly, or call `build()` to have
361	 *   the registry forwarded automatically.
362	 * @returns                BuildResult for this persona × target combination
363	 */
364	export async function buildPersona(
365	  personaYamlPath: string,
366	  suiteName: string,
367	  suiteConfig: SuiteConfig,
368	  sharedMeta: Record<string, unknown>,
369	  partialsMap: Record<string, string>,
370	  config: BuildConfig,
371	  plugins: PersonaBuildPlugin[],
372	  target: string,
373	  agentMap: Record<string, string> = {},
374	  registry: TargetRegistry = defaultRegistry,
375	): Promise<BuildResult> {
376	  // ── 1. Load persona metadata ──────────────────────────────────────────────
377	  const personaMeta = await loadPersonaYaml(personaYamlPath);
378	
379	  // ── 2. Build merged context ───────────────────────────────────────────────
380	  let context = buildContext(personaMeta, sharedMeta, agentMap, target, registry);
381	
382	  // ── 3. Plugin onBuildContext ──────────────────────────────────────────────
383	  // Cast context to PersonaMetadata for the plugin runner (it requires a
384	  // name field which is guaranteed by loadPersonaYaml above).
385	  const personaMetaTyped = personaMeta as PersonaMetadata;
386	  context = runBuildContext(plugins, context, personaMetaTyped, suiteConfig, target);
387	
388	  // ── 4. Render frontmatter ─────────────────────────────────────────────────
389	  const fmTemplate = resolveFrontmatterTemplate(target, plugins, config.frontmatter, registry);
390	  const contentBasename = path.basename(personaYamlPath, '.yaml') + '.md';
391	  const frontmatter = renderFrontmatter(fmTemplate, context, contentBasename);
392	
393	  // ── 5. Load content template ──────────────────────────────────────────────
394	  const contentSubdir = suiteConfig.contentSubdir ?? 'content';
395	  const contentPath = path.join(suiteConfig.srcDir, contentSubdir, contentBasename);
396	  const bodyTemplate = normalizeNewlines(await readFile(contentPath, 'utf8'));
397	
398	  // ── 6. Render body ────────────────────────────────────────────────────────
399	  let body = resolvePartials(bodyTemplate, partialsMap);
400	  body = resolveConditionals(body, context);
401	  body = resolveVariables(body, context, contentBasename);
402	  body = collapseBlankLines(body);
403	  body = ensureBlankLineBeforeHeadings(body);
404	  body = body.trimEnd();
405	
406	  // ── 7. Assemble output ────────────────────────────────────────────────────
407	  let output = normalizeNewlines(`${frontmatter}\n\n${body}\n`);
408	
409	  // ── 8. Plugin onPostRender ────────────────────────────────────────────────
410	  output = runPostRender(plugins, output, personaMetaTyped, target);
411	
412	  // ── 9. Plugin onValidate ──────────────────────────────────────────────────
413	  const validationResults: ValidationResult[] = runValidate(plugins, personaMetaTyped, suiteConfig, target);
414	
415	  // ── 10. Determine output file path ────────────────────────────────────────
416	  // Resolve the registry definition once — used for both outputDirKey (map
417	  // lookup) and filenameContextKey (output filename override).
418	  const def = registry.has(target) ? registry.get(target) : undefined;
419	  const outputDir = resolveOutputDir(target, suiteConfig, def);
420	  // Use the filename context key declared in the target's registry definition,
421	  // falling back to the content basename when absent or unset in context.
422	  const fnKey = def?.filenameContextKey;
423	  const outputBasename =
424	    fnKey && typeof context[fnKey] === 'string'
425	      ? (context[fnKey] as string)
426	      : contentBasename;
427	  const outputPath = path.join(outputDir, outputBasename);
428	
429	  // ── 11. Write (unless check mode) ─────────────────────────────────────────
430	  const check = config.check ?? false;
431	  let written = false;
432	
433	  if (!check) {
434	    await mkdir(outputDir, { recursive: true });
435	    await writeFile(outputPath, output, 'utf8');
436	    written = true;
437	  }
438	
439	  return {
440	    suite: suiteName,
441	    target,
442	    personaYamlPath,
443	    outputPath,
444	    content: output,
445	    validationResults,
446	    written,
447	  };
448	}
